.np-password-input,
[data-np-password-input] {
  --np-password-input-height: calc(var(--np-spacing) * 8);
  --np-password-input-width: 100%;
  --np-password-input-radius: var(--np-radius-md);
  --np-password-input-font-size: 0.875rem;
  --np-password-input-icon-size: 1rem;
  --np-password-input-action-size: calc(var(--np-password-input-height) - 0.5rem);
  --np-password-input-action-radius: var(--np-radius-sm);
  --np-password-input-border: var(--np-input, var(--np-border));
  --np-password-input-bg: transparent;

  box-sizing: border-box;
  display: flex;
  align-items: center;
  width: var(--np-password-input-width);
  max-width: 100%;
  height: var(--np-password-input-height);
  padding-inline-end: calc(
    (var(--np-password-input-height) - var(--np-password-input-action-size) - 2px) / 2
  );
  border: 1px solid var(--np-password-input-border);
  border-radius: var(--np-password-input-radius);
  background-color: var(--np-password-input-bg);
  color: var(--np-foreground);
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.np-password-input-control,
[data-np-password-input-control] {
  box-sizing: border-box;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  margin: 0;
  padding-block: 0;
  padding-inline-start: calc(var(--np-spacing) * 2.5);
  padding-inline-end: var(--np-spacing);
  border: 0;
  border-radius: 0;
  outline: 0;
  background: transparent;
  color: inherit;
  font-family: var(--np-font-sans, inherit);
  font-size: 1rem;
  text-overflow: ellipsis;
}

@media (min-width: 48rem) {
  .np-password-input-control,
  [data-np-password-input-control] {
    font-size: var(--np-password-input-font-size);
  }
}

:is(.np-password-input-control, [data-np-password-input-control])::placeholder {
  color: var(--np-muted-foreground);
}

:is(.np-password-input-control, [data-np-password-input-control])::-ms-reveal,
:is(.np-password-input-control, [data-np-password-input-control])::-ms-clear {
  display: none;
}


.np-password-input-toggle,
[data-np-password-input-toggle],
.np-password-input-action,
[data-np-password-input-action] {
  box-sizing: border-box;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--np-password-input-action-size);
  height: var(--np-password-input-action-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--np-password-input-action-radius);
  background: transparent;
  color: var(--np-muted-foreground);
  font: inherit;
  cursor: pointer;
  transition:
    background-color 150ms ease,
    color 150ms ease,
    box-shadow 150ms ease;
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  )
  + :is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ) {
  margin-inline-start: 2px;
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ):hover {
  background-color: var(--np-muted);
  color: var(--np-foreground);
}

:is(.np-password-input-action, [data-np-password-input-action])[data-copied] {
  color: var(--np-success);
}

:is(.np-password-input-toggle, [data-np-password-input-toggle])[aria-pressed="true"] {
  color: var(--np-foreground);
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ):focus-visible {
  outline: 0;
  background-color: var(--np-muted);
  color: var(--np-foreground);
  box-shadow: 0 0 0 2px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ) svg:not([class*="size-"]) {
  width: var(--np-password-input-icon-size);
  height: var(--np-password-input-icon-size);
}

:is(.np-password-input-toggle, [data-np-password-input-toggle]) .np-password-input-icon-hide {
  display: none;
}

:is(.np-password-input-toggle, [data-np-password-input-toggle])[aria-pressed="true"]
  .np-password-input-icon-show {
  display: none;
}

:is(.np-password-input-toggle, [data-np-password-input-toggle])[aria-pressed="true"]
  .np-password-input-icon-hide {
  display: block;
}

.np-password-input-addon,
[data-np-password-input-addon] {
  box-sizing: border-box;
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: calc(var(--np-spacing) * 1.5);
  padding-inline-start: calc(var(--np-spacing) * 2.5);
  color: var(--np-muted-foreground);
  font-size: var(--np-password-input-font-size);
  white-space: nowrap;
}

:is(.np-password-input-addon, [data-np-password-input-addon]):not(:first-child) {
  padding-inline: 0 calc(var(--np-spacing) * 2);
}

:is(.np-password-input-addon, [data-np-password-input-addon]) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(.np-password-input-addon, [data-np-password-input-addon]) svg:not([class*="size-"]) {
  width: var(--np-password-input-icon-size);
  height: var(--np-password-input-icon-size);
}

:is(.np-password-input-addon, [data-np-password-input-addon]):first-child
  + :is(.np-password-input-control, [data-np-password-input-control]) {
  padding-inline-start: calc(var(--np-spacing) * 2);
}

.np-password-input-caps-lock,
[data-np-password-input-caps-lock] {
  box-sizing: border-box;
  flex: none;
  display: none;
  align-items: center;
  gap: var(--np-spacing);
  height: 1.25rem;
  margin-inline: var(--np-spacing);
  padding-inline: calc(var(--np-spacing) * 1.5);
  border-radius: var(--np-radius-full);
  background-color: color-mix(in oklch, var(--np-warning) 15%, transparent);
  color: color-mix(in oklch, var(--np-warning), var(--np-foreground) 40%);
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}

:is(.np-password-input, [data-np-password-input])[data-capslock]
  :is(.np-password-input-caps-lock, [data-np-password-input-caps-lock]) {
  display: inline-flex;
}

:is(.np-password-input-caps-lock, [data-np-password-input-caps-lock]) svg {
  flex-shrink: 0;
  width: 0.75rem;
  height: 0.75rem;
}

.np-password-input-strength,
[data-np-password-input-strength] {
  --np-password-input-strength-color: var(--np-muted-foreground);
  --np-password-input-strength-track: var(--np-muted);

  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: calc(var(--np-spacing) * 1.5);
  width: 100%;
  font-size: 0.75rem;
  line-height: 1.2;
}

.np-password-input-strength-bars,
[data-np-password-input-strength-bars] {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--np-spacing);
}

.np-password-input-strength-bar,
[data-np-password-input-strength-bar] {
  height: 0.25rem;
  border-radius: var(--np-radius-full);
  background-color: var(--np-password-input-strength-track);
  transition: background-color 150ms ease;
}

.np-password-input-strength-label,
[data-np-password-input-strength-label] {
  color: color-mix(in oklch, var(--np-password-input-strength-color), var(--np-foreground) 40%);
  font-weight: 500;
}

:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="1"] {
  --np-password-input-strength-color: var(--np-destructive);
}

:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="2"] {
  --np-password-input-strength-color: var(--np-warning);
}

:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="3"] {
  --np-password-input-strength-color: color-mix(
    in oklch,
    var(--np-success) 60%,
    var(--np-warning)
  );
}

:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="4"] {
  --np-password-input-strength-color: var(--np-success);
}

:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="1"]
  :is(.np-password-input-strength-bar, [data-np-password-input-strength-bar]):nth-child(-n + 1),
:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="2"]
  :is(.np-password-input-strength-bar, [data-np-password-input-strength-bar]):nth-child(-n + 2),
:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="3"]
  :is(.np-password-input-strength-bar, [data-np-password-input-strength-bar]):nth-child(-n + 3),
:is(.np-password-input-strength, [data-np-password-input-strength])[data-level="4"]
  :is(.np-password-input-strength-bar, [data-np-password-input-strength-bar]):nth-child(-n + 4) {
  background-color: var(--np-password-input-strength-color);
}

.np-password-input-requirements,
[data-np-password-input-requirements] {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: calc(var(--np-spacing) * 1.5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.np-password-input-requirement,
[data-np-password-input-requirement] {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: calc(var(--np-spacing) * 2);
  color: var(--np-muted-foreground);
  font-size: 0.8125rem;
  line-height: 1.2;
  transition: color 150ms ease;
}

:is(.np-password-input-requirement, [data-np-password-input-requirement])[data-met] {
  color: color-mix(in oklch, var(--np-success), var(--np-foreground) 40%);
}

.np-password-input-requirement-icon {
  flex: none;
  width: 0.875rem;
  height: 0.875rem;
}

.np-password-input-requirement-check {
  display: none;
  color: var(--np-success);
}

:is(.np-password-input-requirement, [data-np-password-input-requirement])[data-met]
  .np-password-input-requirement-check {
  display: block;
}

:is(.np-password-input-requirement, [data-np-password-input-requirement])[data-met]
  .np-password-input-requirement-x {
  display: none;
}

.np-password-input-requirement-status {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.np-password-input-requirement-done {
  display: none;
}

:is(.np-password-input-requirement, [data-np-password-input-requirement])[data-met]
  .np-password-input-requirement-done {
  display: block;
}

:is(.np-password-input-requirement, [data-np-password-input-requirement])[data-met]
  .np-password-input-requirement-todo {
  display: none;
}

:is(.np-password-input, [data-np-password-input]):has(
    :where(
      .np-password-input-control:focus-visible,
      [data-np-password-input-control]:focus-visible
    )
  ) {
  border-color: var(--np-ring);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is(.np-password-input, [data-np-password-input]):is(
    [data-readonly],
    :has(input[readonly])
  ) {
  background-color: color-mix(in oklab, var(--np-muted) 50%, transparent);
}

:is(.np-password-input, [data-np-password-input]):is(
    [data-disabled],
    [aria-disabled="true"],
    :has(input:disabled)
  ) {
  opacity: 0.5;
  pointer-events: none;
}

:is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ):is(:disabled, [aria-disabled="true"], [data-disabled]) {
  opacity: 0.5;
  pointer-events: none;
}

:is(.np-password-input, [data-np-password-input]):is(
    [data-disabled],
    [aria-disabled="true"],
    :has(input:disabled)
  )
  :is(
    .np-password-input-toggle,
    [data-np-password-input-toggle],
    .np-password-input-action,
    [data-np-password-input-action]
  ) {
  opacity: 1;
}

:is(.np-field, [data-np-field])[data-invalid]
  :is(.np-password-input, [data-np-password-input]),
:is(.np-password-input, [data-np-password-input]):is(
    [data-invalid],
    :has([aria-invalid="true"])
  ) {
  border-color: var(--np-destructive);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-destructive), transparent 80%);
}

.np-password-input-xs,
:is(.np-password-input, [data-np-password-input])[data-size="xs"] {
  --np-password-input-height: calc(var(--np-spacing) * 6);
  --np-password-input-radius: min(var(--np-radius-md), 10px);
  --np-password-input-font-size: 0.75rem;
  --np-password-input-icon-size: 0.75rem;
}

.np-password-input-sm,
:is(.np-password-input, [data-np-password-input])[data-size="sm"] {
  --np-password-input-height: calc(var(--np-spacing) * 7);
  --np-password-input-radius: min(var(--np-radius-md), 12px);
  --np-password-input-icon-size: 0.875rem;
}

.np-password-input-lg,
:is(.np-password-input, [data-np-password-input])[data-size="lg"] {
  --np-password-input-height: calc(var(--np-spacing) * 9);
}

:is(.dark, [data-theme="dark"]) :is(.np-password-input, [data-np-password-input]) {
  --np-password-input-bg: color-mix(in oklab, var(--np-password-input-border) 30%, transparent);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"]) :is(.np-password-input, [data-np-password-input]) {
    --np-password-input-bg: color-mix(in oklab, var(--np-password-input-border) 30%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-password-input,
  [data-np-password-input],
  .np-password-input-toggle,
  [data-np-password-input-toggle],
  .np-password-input-action,
  [data-np-password-input-action],
  .np-password-input-strength-bar,
  [data-np-password-input-strength-bar],
  .np-password-input-requirement,
  [data-np-password-input-requirement] {
    transition: none;
  }
}

; (function () {
  var ROOT = ".np-password-input, [data-np-password-input]"
  var CONTROL = ".np-password-input-control, [data-np-password-input-control]"
  var TOGGLE = ".np-password-input-toggle, [data-np-password-input-toggle]"
  var ACTION = ".np-password-input-action, [data-np-password-input-action]"
  var STRENGTH =
    ".np-password-input-strength, [data-np-password-input-strength]"
  var REQUIREMENTS =
    ".np-password-input-requirements, [data-np-password-input-requirements]"
  var FIELD = ".np-field, [data-np-field]"
  var LABELS = ["Enter a password", "Weak", "Fair", "Good", "Strong"]
  var CHARACTERS =
    "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%"
  var idCounter = 0

  var RULES = {
    length: function (value, element) {
      return value.length >= (Number(element.getAttribute("data-min")) || 8)
    },
    number: function (value) {
      return /\d/.test(value)
    },
    letter: function (value) {
      return /[A-Za-z]/.test(value)
    },
    case: function (value) {
      return /[a-z]/.test(value) && /[A-Z]/.test(value)
    },
    symbol: function (value) {
      return /[^A-Za-z0-9]/.test(value)
    },
  }

  function defaultScore(value) {
    if (!value) return 0
    var passed = [
      value.length >= 8,
      /\d/.test(value),
      /[a-z]/.test(value) && /[A-Z]/.test(value),
      /[^A-Za-z0-9]/.test(value),
    ].filter(Boolean).length
    return Math.max(1, passed)
  }

  function randomPassword(length) {
    var out = ""
    var bytes
    if (window.crypto && window.crypto.getRandomValues)
      bytes = window.crypto.getRandomValues(new Uint32Array(length))
    else {
      bytes = []
      for (var i = 0; i < length; i++)
        bytes.push(Math.floor(Math.random() * 4294967296))
    }
    for (var j = 0; j < length; j++)
      out += CHARACTERS.charAt(bytes[j] % CHARACTERS.length)
    return out
  }

  function init(root) {
    if (root.hasAttribute("data-np-password-input-ready")) return
    var input = root.querySelector(CONTROL)
    if (!input) return
    root.setAttribute("data-np-password-input-ready", "")

    var toggle = root.querySelector(TOGGLE)
    var scope = root.closest(FIELD) || root.parentElement || root
    var strength = scope.querySelector(STRENGTH)
    var requirements = scope.querySelector(REQUIREMENTS)
    var form = input.form

    if (!input.id) input.id = "np-password-input-" + ++idCounter

    // ── visibility ──────────────────────────────────────────────
    function isVisible() {
      return input.type === "text"
    }

    function setVisible(visible, reason, event) {
      if (visible === isVisible()) return false
      input.type = visible ? "text" : "password"
      root.toggleAttribute("data-visible", visible)
      if (toggle)
        toggle.setAttribute("aria-pressed", visible ? "true" : "false")
      root.dispatchEvent(
        new CustomEvent("np-password-input:visible", {
          bubbles: true,
          detail: {
            visible: visible,
            reason: reason,
            originalEvent: event || null,
          },
        })
      )
      return true
    }

    // Match the markup the page started with.
    root.toggleAttribute("data-visible", isVisible())
    if (toggle) {
      toggle.setAttribute("aria-pressed", isVisible() ? "true" : "false")
      if (!toggle.hasAttribute("aria-controls"))
        toggle.setAttribute("aria-controls", input.id)
      if (!toggle.hasAttribute("type")) toggle.setAttribute("type", "button")

      // Keep the caret where it is when the pointer presses the toggle.
      toggle.addEventListener("mousedown", function (event) {
        event.preventDefault()
      })
      toggle.addEventListener("click", function (event) {
        var hadFocus = document.activeElement === input
        var start = input.selectionStart,
          end = input.selectionEnd,
          direction = input.selectionDirection
        if (!setVisible(!isVisible(), "toggle-press", event)) return
        // A pointer press from elsewhere brings focus back; a keyboard press keeps it on the toggle.
        if (event.detail > 0 && !hadFocus) input.focus({ preventScroll: true })
        if (start !== null && end !== null) {
          try {
            input.setSelectionRange(start, end, direction || undefined)
          } catch {
            // Ignore errors.
          }
        }
      })
    }

    // ── hide again on submit, reset and page hide ───────────────
    if (form) {
      form.addEventListener("submit", function (event) {
        // setVisible switches the input back to type="password" synchronously,
        // so the browser reads (and offers to save) a password field.
        setVisible(false, "form-submit", event)
      })
      form.addEventListener("reset", function (event) {
        setVisible(false, "reset", event)
        setTimeout(update, 0) // after the browser has restored the default value
      })
    }
    window.addEventListener("pagehide", function (event) {
      setVisible(false, "page-hide", event)
    })

    // ── Caps Lock ───────────────────────────────────────────────
    function syncCapsLock(event) {
      root.toggleAttribute(
        "data-capslock",
        !!(event.getModifierState && event.getModifierState("CapsLock"))
      )
    }
    input.addEventListener("keydown", syncCapsLock)
    input.addEventListener("keyup", syncCapsLock)
    input.addEventListener("mousedown", syncCapsLock)
    input.addEventListener("blur", function () {
      root.removeAttribute("data-capslock")
    })

    // ── strength + requirements ─────────────────────────────────
    function update() {
      var value = input.value
      var scorer =
        (window.NepuiPasswordInput && window.NepuiPasswordInput.score) ||
        defaultScore
      var level = Math.min(4, Math.max(0, Math.round(scorer(value))))

      if (strength) {
        var labels = (strength.getAttribute("data-labels") || "").split("|")
        var text = (labels.length === 5 ? labels : LABELS)[level]
        strength.setAttribute("data-level", String(level))
        strength.setAttribute("aria-valuenow", String(level))
        strength.setAttribute("aria-valuetext", text)
        var label = strength.querySelector(
          ".np-password-input-strength-label, [data-np-password-input-strength-label]"
        )
        if (label) label.textContent = text
      }

      if (requirements) {
        Array.prototype.forEach.call(
          requirements.querySelectorAll("li"),
          function (item) {
            var met = false
            var pattern = item.getAttribute("data-pattern")
            var rule = item.getAttribute("data-rule")
            if (pattern) {
              try {
                met = new RegExp(pattern).test(value)
              } catch {
                // Ignore errors.
              }
            } else if (rule && RULES[rule]) met = RULES[rule](value, item)
            item.toggleAttribute("data-met", met)
          }
        )
      }

      root.dispatchEvent(
        new CustomEvent("np-password-input:input", {
          bubbles: true,
          detail: { value: value, score: level },
        })
      )
    }
    input.addEventListener("input", update)
    update()

    // ── actions: copy, clear, generate ──────────────────────────
    Array.prototype.forEach.call(
      root.querySelectorAll(ACTION),
      function (button) {
        button.addEventListener("mousedown", function (event) {
          event.preventDefault()
        })
        button.addEventListener("click", function () {
          var action = button.getAttribute("data-action")
          if (action === "copy") {
            if (!input.value || !navigator.clipboard) return
            navigator.clipboard.writeText(input.value).then(function () {
              var original = button.getAttribute("aria-label")
              button.setAttribute("data-copied", "")
              button.setAttribute("aria-label", "Copied")
              setTimeout(function () {
                button.removeAttribute("data-copied")
                if (original) button.setAttribute("aria-label", original)
              }, 1500)
            })
          } else if (action === "clear") {
            input.value = ""
            input.dispatchEvent(new Event("input", { bubbles: true }))
            input.focus()
